void ee_mixer_host_set_data(void *s, const void *data);

/// # Safety
/// `s` is a live sample.
bool ee_mixer_host_is_looping(void *s);

/// # Safety
/// `s` is a live sample.
float ee_mixer_host_pan(void *s);

/// # Safety
/// `s` is a live sample.
float ee_mixer_host_pitch(void *s);

/// # Safety
/// `s` is a live sample.
float ee_mixer_host_volume(void *s);

/// # Safety
